const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];let currentDashboard='CAFÉ',currentDashboardCycle='',allTransactions=[],allProducers=[],currentDailyDate=new Date().toISOString().slice(0,10),editingTransactionId=0;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
