const dateBR=s=>s?String(s).split('-').reverse().join('/'):'-';
function printSection(title,selector,orientation='landscape'){
  const el=document.querySelector(selector);
  if(!el){toast('Área de impressão não encontrada');return}
  const win=window.open('','_blank','width=1200,height=850');
  if(!win){toast('O navegador bloqueou a janela de impressão. Permita pop-ups para este endereço.');return}
  const logo=document.querySelector('.brand img')?.src||'./assets/logo-ouro-verde.png';
  const now=new Date().toLocaleString('pt-BR');
  win.document.open();
  win.document.write(`<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>${esc(title)}</title><style>
  @page{size:A4 ${orientation};margin:10mm}
  *{box-sizing:border-box}body{font-family:Arial,sans-serif;color:#17211f;margin:0;background:#fff;font-size:11px}
  .print-head{display:flex;align-items:center;justify-content:space-between;border-bottom:3px solid #1e8f38;padding-bottom:8px;margin-bottom:14px}.print-head img{width:115px;max-height:55px;object-fit:contain}.print-head h1{font-size:18px;margin:0}.print-head p{margin:4px 0 0;color:#60706a}.print-date{text-align:right;font-size:10px;color:#60706a}
  button,input,select,.report-actions,.report-filters,.report-tabs,.daily-date-actions,.dashboard-toolbar .module-switch,.print-cycle-report,.producer-search-grid,.producer-form-actions,.table-btn,.head-actions{display:none!important}
  .panel,.kpi,.daily-segment,.lot-card{box-shadow:none!important;border:1px solid #cfdad4!important;break-inside:avoid;background:#fff!important}.panel{padding:10px;margin-bottom:10px}.page{display:block!important;padding:0!important}.kpis,.report-kpis,.central-kpis{display:grid!important;grid-template-columns:repeat(4,1fr)!important;gap:8px!important}.kpi{padding:10px!important}.kpi i{display:none}.kpi small,.kpi strong{display:block}.kpi strong{font-size:15px}.dashboard-grid,.report-grid-top,.report-grid-bottom,.central-grid{display:block!important}.bars{height:160px!important}.table-wrap{overflow:visible!important}table{width:100%;border-collapse:collapse;font-size:9px}th,td{padding:5px;border-bottom:1px solid #dfe7e3;text-align:left}thead{display:table-header-group}tr{break-inside:avoid}.report-detail{display:block!important}.report-note{font-size:9px}.modal,.hidden,aside,header{display:none!important}
  </style></head><body><div class="print-head"><img src="${logo}"><div><h1>${esc(title)}</h1><p>Ouro Verde ERP — relatório para conferência e arquivo</p></div><div class="print-date">Emitido em<br><b>${now}</b></div></div><main>${el.outerHTML}</main><script>window.onload=()=>{setTimeout(()=>{window.print()},350)};<\/script></body></html>`);
  win.document.close();
}

async function api(url,opt={}){const r=await fetch(url,{headers:{'Content-Type':'application/json',...(opt.headers||{})},...opt});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'Erro');return d}
function toast(m){const t=$('#toast');t.textContent=m;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2800)}
function showPage(n){$$('.page').forEach(x=>x.classList.remove('active'));$('#page-'+n).classList.add('active');$$('nav button[data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===n));const title={dashboard:'Dashboard',coffee:'Módulo Café',cacao:'Módulo Cacau',nuts:'Módulo Castanhas',producers:'Produtores',tickets:'Tickets',reports:'Relatórios',audit:'Auditoria',deposits:'Depósitos',settings:'Configurações'}[n];$('#pageTitle').textContent=title;$('#crumb').textContent=n==='central'?'CENTRAL DE OPERAÇÕES':n==='dashboard'?'GESTÃO POR LOTES':'OURO VERDE ERP';if(n==='central')loadCentral();if(n==='coffee'||n==='cacao'||n==='nuts'||n==='tickets')loadTransactions();if(n==='producers')renderProducerTable();if(n==='reports')renderReports();if(n==='deposits')loadDeposits();if(n==='audit')loadAudit();if(n==='settings')loadSettings()}
async function boot(){try{const d=await api('/api/me');$('#login').classList.add('hidden');$('#erp').classList.remove('hidden');$('#userName').textContent=d.user.name;$('#today').textContent=new Date().toLocaleDateString('pt-BR',{day:'2-digit',month:'long',year:'numeric'});await Promise.all([loadProducers(),loadCentral(),loadDashboard(),loadDailyEntries(),loadTransactions(),loadSettings(),loadAudit()])}catch{}}
$('#loginForm').addEventListener('submit',async e=>{e.preventDefault();try{await api('/api/login',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});location.reload()}catch(err){$('#loginError').textContent=err.message}});
$('#logout').onclick=async()=>{await api('/api/logout',{method:'POST'});location.reload()};
$$('[data-page]').forEach(b=>b.addEventListener('click',()=>showPage(b.dataset.page)));
async function loadProducers(){const d=await api('/api/producers');allProducers=d.rows;renderProducerTable();filterTransactionProducers();fillDepositProducerOptions();resolveDepositCpf()}
function onlyDigits(v){return String(v||'').replace(/\D/g,'')}
function renderProducerTable(){const nameQ=($('#producerSearchName')?.value||'').trim().toLowerCase(),cpfQ=onlyDigits($('#producerSearchCpf')?.value);const rows=allProducers.filter(p=>(!nameQ||String(p.name||'').toLowerCase().includes(nameQ))&&(!cpfQ||onlyDigits(p.cpf).includes(cpfQ)));$('#producerRows').innerHTML=rows.map(p=>`<tr><td>${esc(p.code||p.id)}</td><td>${esc(p.type||'')}</td><td><b>${esc(p.name)}</b><small>${esc(p.classification||'')}</small></td><td>${esc(p.cpf)}</td><td>${esc(p.city||'')}/${esc(p.uf||'')}</td><td>${esc(p.caf||'')}</td><td><button class="table-btn" onclick="editProducer(${p.id})">Editar</button></td></tr>`).join('')||'<tr><td colspan="7">Nenhum produtor localizado.</td></tr>'}
function filterTransactionProducers(){const nameQ=($('#transactionProducerName')?.value||'').trim().toLowerCase(),cpfQ=onlyDigits($('#transactionProducerCpf')?.value),select=$('#producerSelect');if(!select)return;const current=select.value;let rows=allProducers.filter(p=>(!nameQ||String(p.name||'').toLowerCase().includes(nameQ))&&(!cpfQ||onlyDigits(p.cpf).includes(cpfQ)));if(!nameQ&&!cpfQ)rows=rows.slice(0,150);select.innerHTML='<option value="">Selecione...</option>'+rows.map(p=>`<option value="${p.id}">${esc(p.name)} — ${esc(p.cpf)}</option>`).join('');const exact=cpfQ?rows.find(p=>onlyDigits(p.cpf)===cpfQ):null;if(exact)select.value=exact.id;else if(rows.some(p=>String(p.id)===String(current)))select.value=current;const chosen=allProducers.find(p=>String(p.id)===String(select.value));const box=$('#transactionProducerResolved');if(box)box.innerHTML=chosen?`<b>${esc(chosen.name)}</b><span>${esc(chosen.cpf||'')} • Código ${esc(chosen.code||chosen.id)}</span>`:'Nenhum produtor selecionado.'}
$('#producerSearchName').addEventListener('input',renderProducerTable);$('#producerSearchCpf').addEventListener('input',renderProducerTable);$('#producerPrint')?.addEventListener('click',()=>printSection('Relatório de produtores','#page-producers .two-col > .panel:last-child','landscape'));$('#transactionProducerName').addEventListener('input',filterTransactionProducers);$('#transactionProducerCpf').addEventListener('input',filterTransactionProducers);$('#producerSelect').addEventListener('change',filterTransactionProducers);
function resetProducerForm(){const f=$('#producerForm');f.reset();$('#producerEditId').value='';$('#producerFormTitle').textContent='Novo produtor';$('#producerSubmitButton').textContent='Cadastrar produtor';$('#producerCancelEdit').classList.add('hidden');f.uf.value='RO'}
window.editProducer=id=>{const p=allProducers.find(x=>Number(x.id)===Number(id));if(!p)return;const f=$('#producerForm');for(const [k,v] of Object.entries(p))if(f.elements[k])f.elements[k].value=v??'';$('#producerEditId').value=p.id;$('#producerFormTitle').textContent='Editar produtor';$('#producerSubmitButton').textContent='Salvar alterações';$('#producerCancelEdit').classList.remove('hidden');f.scrollIntoView({behavior:'smooth',block:'start'})};
$('#producerCancelEdit').onclick=resetProducerForm;
$('#producerForm').addEventListener('submit',async e=>{e.preventDefault();try{const payload=Object.fromEntries(new FormData(e.target)),id=payload.id;delete payload.id;await api(id?'/api/producers/'+id:'/api/producers',{method:id?'PUT':'POST',body:JSON.stringify(payload)});resetProducerForm();await loadProducers();toast(id?'Cadastro atualizado com sucesso':'Produtor cadastrado com sucesso')}catch(err){toast(err.message)}});
async function loadDashboard(){const qs=new URLSearchParams({product:currentDashboard});if(currentDashboardCycle)qs.set('cycle',currentDashboardCycle);const d=await api('/api/dashboard?'+qs.toString());const cycleSelect=$('#dashboardCycle'),previous=currentDashboardCycle;cycleSelect.innerHTML='<option value="">Todos os ciclos/lotes</option>'+d.cycles.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('');cycleSelect.value=d.cycles.includes(previous)?previous:'';currentDashboardCycle=cycleSelect.value;$('#dashboardContext').innerHTML=currentDashboardCycle?`<b>Relatório do ciclo/lote ${esc(currentDashboardCycle)}</b><span>Os indicadores abaixo consideram exclusivamente as movimentações deste ciclo/lote.</span>`:`<b>Visão geral de ${currentDashboard==='CAFÉ'?'café':currentDashboard==='CACAU'?'cacau':'castanhas'}</b><span>Consolidado de todos os ciclos/lotes cadastrados.</span>`;const icons=['📥','🛒','⚖','🏷','R$','%','R$','🎫','✓','↘','R$'],items=[['Depósito líquido do ciclo',num(d.deposits)+' kg'],['Venda líquida do ciclo',num(d.purchases)+' kg'],['Saldo de depósito',num(d.balance)+' kg'],['Peso bruto no ciclo',num(d.gross_weight)+' kg'],['Valor bruto do ciclo',money(d.gross_value)],['Fundo Rural',money(d.rural_fund)],['Valor líquido do ciclo',money(d.net_value)],['Quantidade de tickets',d.tickets],['Eficiência física do lote',num(d.weight_efficiency)+'%'],['Diferença bruto x líquido',num(d.weight_loss)+' kg'],['Preço médio do ciclo',money(d.average_price)+'/kg']];$('#dashboardKpis').innerHTML=items.map((x,i)=>`<article class="kpi"><i>${icons[i]}</i><small>${x[0]}</small><strong>${x[1]}</strong></article>`).join('');const max=Math.max(d.deposits,d.purchases,Math.abs(d.balance),1);$('#summaryBars').innerHTML=[['Depósitos líquidos',d.deposits],['Vendas líquidas',d.purchases],['Saldo líquido',Math.max(0,d.balance)]].map(x=>`<div class="bar-item"><div class="bar" style="height:${Math.max(12,x[1]/max*170)}px"></div><b>${x[0]}<br>${num(x[1])} kg</b></div>`).join('');$('#recentRows').innerHTML=d.recent.map(r=>`<div class="recent-row"><div><b>${esc(r.producer_name)}</b><small>${dateBR(r.date)} • ${esc(r.operation)} • ${esc(r.cycle)}</small></div><span>${num(r.equivalent_weight)} kg</span></div>`).join('')||'<p>Nenhum registro ainda.</p>'}
$$('.module-switch button[data-product]').forEach(b=>b.onclick=()=>{$$('.module-switch button').forEach(x=>x.classList.remove('active'));b.classList.add('active');currentDashboard=b.dataset.product;currentDashboardCycle='';loadDashboard()});$('#dashboardCycle').onchange=e=>{currentDashboardCycle=e.target.value;loadDashboard()};$('#printCycleReport').onclick=()=>printSection('Relatório por ciclo/lote','#page-dashboard','landscape');
async function loadDailyEntries(){const input=$('#dailyDate');if(!input)return;if(!input.value)input.value=currentDailyDate;currentDailyDate=input.value;try{const d=await api('/api/daily-summary?date='+encodeURIComponent(currentDailyDate));$('#dailyTotal').innerHTML=`<div><small>DATA SELECIONADA</small><strong>${dateBR(d.date)}</strong></div><div><small>ENTRADA TOTAL</small><strong>${num(d.total.weight)} kg</strong></div><div><small>TICKETS</small><strong>${d.total.tickets}</strong></div><div><small>PRODUTORES</small><strong>${d.total.producers}</strong></div>`;const meta={'CAFÉ':['☕','Café','coffee'],'CACAU':['◉','Cacau','cacao'],'CASTANHAS':['◈','Castanhas','nuts']};$('#dailySegments').innerHTML=d.products.map(x=>{const m=meta[x.product]||['•',x.product,''];const total=Math.max(x.purchases+x.deposits,1),pw=x.purchases/total*100,dw=x.deposits/total*100;return `<article class="daily-segment ${m[2]}"><div class="daily-segment-head"><div><small>${esc(x.product)}</small><h4>${m[1]}</h4></div><span>${m[0]}</span></div><div class="daily-weight">${num(x.weight)} kg</div><div class="daily-caption">Peso líquido recebido/movimentado no dia</div><div class="daily-mini-grid"><div><small>Compras</small><b>${num(x.purchases)} kg</b></div><div><small>Depósitos</small><b>${num(x.deposits)} kg</b></div><div><small>Tickets</small><b>${x.tickets}</b></div><div><small>Produtores</small><b>${x.producers}</b></div></div>${x.weight>0?`<div class="daily-progress" aria-label="Distribuição entre compras e depósitos"><span class="purchase" style="width:${pw}%"></span><span class="deposit" style="width:${dw}%"></span></div><div class="daily-legend"><span><i></i>Compras</span><span><i></i>Depósitos</span></div><span class="daily-status">Movimento registrado</span>`:`<div class="daily-empty">Nenhuma entrada registrada nesta data.</div><span class="daily-status">${x.product==='CASTANHAS'?'Módulo preparado':'Sem movimento'}</span>`}</article>`}).join('')}catch(err){$('#dailySegments').innerHTML=`<p>${esc(err.message)}</p>`}}
function changeDailyDate(days){const d=new Date((currentDailyDate||new Date().toISOString().slice(0,10))+'T12:00:00');d.setDate(d.getDate()+days);currentDailyDate=d.toISOString().slice(0,10);$('#dailyDate').value=currentDailyDate;loadDailyEntries()}
$('#dailyDate').addEventListener('change',e=>{currentDailyDate=e.target.value;loadDailyEntries()});$('#dailyPrev').onclick=()=>changeDailyDate(-1);$('#dailyNext').onclick=()=>changeDailyDate(1);$('#dailyToday').onclick=()=>{currentDailyDate=new Date().toISOString().slice(0,10);$('#dailyDate').value=currentDailyDate;loadDailyEntries()};
function openForm(product){editingTransactionId=0;const f=$('#transactionForm');f.reset();f.elements.transaction_id.value='';$('#manualValuesSection')?.classList.add('hidden');$('#transactionSubmit').textContent='Salvar e gerar ticket';f.product.value=product;f.attendant.value='';f.date.value=new Date().toISOString().slice(0,10);f.cycle.value=(String(new Date().getMonth()+1).padStart(2,'0'))+'/'+String(new Date().getFullYear()).slice(-2);$('#transactionProducerName').value='';$('#transactionProducerCpf').value='';filterTransactionProducers();$('#formEyebrow').textContent=product==='CACAU'?'MÓDULO CACAU':product==='CASTANHAS'?'MÓDULO CASTANHAS':'MÓDULO CAFÉ';$('#formTitle').textContent=product==='CACAU'?'Novo lançamento diário de cacau':product==='CASTANHAS'?'Novo lançamento de castanhas':'Novo lançamento de café';const ops=product==='CACAU'?['Compra do Produtor','Depósito','Compra do Cacau Depositado','Retirada do Depósito']:product==='CASTANHAS'?['Compra do Produtor','Depósito','Compra da Castanha Depositada','Retirada do Depósito']:['Compra do Produtor','Depósito','Compra do Café Depositado','Retirada do Depósito'];f.operation.innerHTML=ops.map(x=>`<option>${x}</option>`).join('');$('#subtypeLabel').style.display=product==='CAFÉ'?'flex':'none';$('#yieldLabel').style.display=product==='CAFÉ'?'flex':'none';$('#defectsLabel').style.display=product==='CAFÉ'?'flex':'none';$$('.cacao-only').forEach(x=>x.style.display=product==='CACAU'?(x.classList.contains('section-title')?'block':'flex'):'none');f.moisture.value=product==='CACAU'?9:product==='CASTANHAS'?0:13;$('#formModal').classList.remove('hidden');updateForm();calculate()}
$$('.open-form').forEach(b=>b.onclick=()=>openForm(b.dataset.form));$('#newCoffee').onclick=()=>openForm('CAFÉ');$('#newCacao').onclick=()=>openForm('CACAU');$('#newNuts').onclick=()=>openForm('CASTANHAS');$$('[data-close]').forEach(x=>x.onclick=()=>$('#formModal').classList.add('hidden'));
function formData(){const b=Object.fromEntries(new FormData($('#transactionForm')));['producer_id','gross_weight','moisture','yield_value','defects','price','mold','brocade'].forEach(k=>b[k]=Number(b[k]||0));return b}
function isStoredMovement(op){return op==='Compra do Café Depositado'||op==='Compra do Cacau Depositado'||op==='Retirada do Depósito'}
async function loadSelectedBalance(){const b=formData(),box=$('#depositBalance');if(!box)return;const needs=isStoredMovement(b.operation);box.classList.toggle('hidden',!needs);if(!needs){box.innerHTML='';return}if(!b.producer_id||!b.cycle||!b.product){box.innerHTML='<small>SALDO DO PRODUTOR</small><strong>Selecione o produtor e informe o ciclo/lote.</strong>';return}try{const d=await api(`/api/balance?producer=${b.producer_id}&cycle=${encodeURIComponent(b.cycle)}&product=${encodeURIComponent(b.product)}`);box.innerHTML=`<small>SALDO DISPONÍVEL — ${esc(b.cycle)}</small><strong>${num(d.balance)} kg</strong><span>O sistema impedirá movimentação superior a esse saldo.</span>`}catch(err){box.innerHTML='<strong>Não foi possível consultar o saldo.</strong>'}}
function updateForm(){const b=formData(),stored=isStoredMovement(b.operation),purchase=b.operation?.startsWith('Compra');$('#priceLabel').style.display=purchase?'flex':'none';$('#yieldLabel').style.display=b.product==='CAFÉ'&&b.subtype==='Coco'&&!stored?'flex':'none';$('#defectsLabel').style.display=b.product==='CAFÉ'&&!stored?'flex':'none';$('#subtypeLabel').style.display=b.product==='CAFÉ'&&!stored?'flex':'none';$$('.cacao-only').forEach(x=>x.style.display=b.product==='CACAU'&&!stored?(x.classList.contains('section-title')?'block':'flex'):'none');const moisture=$('#transactionForm [name=moisture]').closest('label');moisture.style.display=stored?'none':'flex';$('#weightLabel').childNodes[0].nodeValue=stored?'Quantidade a movimentar (kg)':'Peso bruto (kg)';const action=b.operation==='Depósito'?'Novo depósito':b.operation?.includes('Depositado')?'Compra de produto depositado':b.operation==='Retirada do Depósito'?'Retirada de depósito':'Compra do produtor';$('#formTitle').textContent=`${action} — ${b.product==='CACAU'?'cacau':b.product==='CASTANHAS'?'castanhas':'café'}`;loadSelectedBalance()}
async function calculate(){updateForm();const b=formData();if(!b.product)return;try{const c=await api('/api/calculate',{method:'POST',body:JSON.stringify(b)}),stored=isStoredMovement(b.operation);const unitLabel=b.product==='CACAU'?'Unidades':'Sacas';let cells=stored?[['Quantidade da movimentação',num(c.equivalent_weight)+' kg']]:[['Peso líquido',num(c.physical_net_weight)+' kg'],[unitLabel,num(c.units)],['Desc. umidade',num(c.moisture_discount)+' kg'],['Desc. fixo',num(c.fixed_discount)+' kg']];if(b.product==='CACAU'&&!stored)cells=cells.concat([['Mofado informado',num(b.mold)+' kg'],['Desconto mofado (5%)',num(c.mold_discount)+' kg'],['Brocado informado',num(b.brocade)+' kg'],['Desconto brocado (20%)',num(c.brocade_discount)+' kg'],['Desconto total',num(c.total_discount)+' kg']]);if(b.operation?.startsWith('Compra'))cells=cells.concat([['Valor bruto',money(c.gross_value)],['Fundo Rural',money(c.rural_fund)],['Valor líquido',money(c.net_value)]]);let memory=stored?(b.operation==='Retirada do Depósito'?'A retirada reduz o saldo do produtor e não gera pagamento.':'A compra utiliza o peso já depositado, baixa o saldo e gera o pagamento sem aplicar novamente os descontos de recebimento.'):(b.operation==='Depósito'?'O peso líquido apurado será acrescentado ao saldo depositado do produtor e não gerará pagamento.':b.product==='CACAU'?`Peso líquido = peso bruto − desconto fixo − desconto de umidade − 5% do peso informado como mofado − 20% do peso informado como brocado.`:b.subtype==='Coco'?`Sacas = ${num(b.gross_weight)} ÷ 41 × ${num(b.yield_value)} ÷ 60,2, usando duas casas sem arredondar.`:`Sacas = peso líquido ÷ 60,2, usando duas casas sem arredondar.`);$('#calcPreview').innerHTML=`<div class="calc-grid">${cells.map(x=>`<div><small>${x[0]}</small><b>${x[1]}</b></div>`).join('')}</div><p class="calc-memory">${memory}</p>`}catch(err){toast(err.message)}}
$('#transactionForm').addEventListener('input',calculate);$('#transactionForm').addEventListener('change',calculate);
$('#transactionForm').addEventListener('submit',async e=>{e.preventDefault();try{const payload=formData(),id=Number(payload.transaction_id||editingTransactionId||0);delete payload.transaction_id;const d=await api(id?'/api/transactions/'+id:'/api/transactions',{method:id?'PUT':'POST',body:JSON.stringify(payload)});$('#formModal').classList.add('hidden');editingTransactionId=0;await Promise.all([loadTransactions(),loadDashboard(),loadDailyEntries()]);toast(id?'Ticket atualizado com sucesso':'Lançamento salvo e ticket gerado');showTicket(d.id)}catch(err){toast(err.message)}});
window.editTransaction=async id=>{try{const r=(await api('/api/transactions/'+id)).row;editingTransactionId=id;const f=$('#transactionForm');f.reset();f.elements.transaction_id.value=id;f.product.value=r.product;f.date.value=r.date||'';f.ticket.value=r.ticket||'';f.cycle.value=r.cycle||'';const ops=r.product==='CACAU'?['Compra do Produtor','Depósito','Compra do Cacau Depositado','Retirada do Depósito']:r.product==='CASTANHAS'?['Compra do Produtor','Depósito','Compra da Castanha Depositada','Retirada do Depósito']:['Compra do Produtor','Depósito','Compra do Café Depositado','Retirada do Depósito'];f.operation.innerHTML=ops.map(x=>`<option>${esc(x)}</option>`).join('');f.operation.value=r.operation;f.attendant.value=r.attendant||'';$('#transactionProducerName').value=r.producer_name||'';$('#transactionProducerCpf').value=r.producer_cpf||'';filterTransactionProducers();if(![...f.producer_id.options].some(o=>String(o.value)===String(r.producer_id))){const o=document.createElement('option');o.value=r.producer_id;o.textContent=`${r.producer_name||'Produtor'} — ${r.producer_cpf||''}`;f.producer_id.appendChild(o)}f.producer_id.value=r.producer_id;f.subtype.value=r.subtype||'Limpo';f.gross_weight.value=r.gross_weight||0;f.moisture.value=r.moisture||0;f.yield_value.value=r.yield_value||0;f.defects.value=r.defects||0;f.price.value=r.price||0;f.mold.value=r.mold||0;f.brocade.value=r.brocade||0;f.notes.value=r.notes||'';f.manual_net_weight.value=r.equivalent_weight??r.physical_net_weight??0;f.manual_gross_value.value=r.gross_value??0;f.manual_rural_fund.value=r.rural_fund??0;f.manual_net_value.value=r.net_value??0;$('#formEyebrow').textContent='EDIÇÃO DE TICKET';$('#formTitle').textContent=`Editar ticket ${r.ticket}`;$('#manualValuesSection')?.classList.remove('hidden');$('#transactionSubmit').textContent='Salvar alterações';$('#formModal').classList.remove('hidden');updateForm();calculate()}catch(err){toast(err.message)}};
async function loadTransactions(){const d=await api('/api/transactions');allTransactions=d.rows;renderProductList('CAFÉ','#coffeeList');renderProductList('CACAU','#cacaoList');renderProductList('CASTANHAS','#nutsList');renderTickets();if(document.querySelector('#page-reports.active'))renderReports()}
function renderProductList(product,target){const rows=allTransactions.filter(r=>r.product===product).slice(0,20);$(target).innerHTML=`<div class="panel-head"><div><small>HISTÓRICO</small><h3>Últimos lançamentos de ${product==='CAFÉ'?'café':product==='CACAU'?'cacau':'castanhas'}</h3></div></div><div class="table-wrap"><table><thead><tr><th>Data</th><th>Ticket</th><th>Produtor</th><th>Operação</th><th>Atendente</th><th>Peso bruto</th><th>Peso líquido</th><th>Valor líquido</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td>${dateBR(r.date)}</td><td><b>${esc(r.ticket)}</b></td><td>${esc(r.producer_name)}</td><td><span class="op">${esc(r.operation)}</span></td><td>${esc(r.attendant||'-')}</td><td>${num(r.gross_weight)} kg</td><td>${num(r.equivalent_weight)} kg</td><td>${money(r.net_value)}</td><td><div class="row-actions"><button class="table-btn" onclick="showTicket(${r.id})">Ver</button><button class="table-btn edit" onclick="editTransaction(${r.id})">Editar</button></div></td></tr>`).join('')||'<tr><td colspan="9">Nenhum lançamento.</td></tr>'}</tbody></table></div>`}
function renderTickets(){const product=$('#ticketProduct').value,q=($('#ticketSearch')?.value||'').trim().toLowerCase(),rows=allTransactions.filter(r=>(!product||r.product===product)&&(!q||String(r.ticket||'').toLowerCase().includes(q)));$('#ticketSearchInfo').textContent=q?`${rows.length} ticket(s) localizado(s) para “${$('#ticketSearch').value.trim()}”.`:`${rows.length} ticket(s) exibido(s).`;$('#ticketRows').innerHTML=rows.map(r=>`<tr><td>${dateBR(r.date)}</td><td><b>${esc(r.ticket)}</b></td><td>${esc(r.product)}</td><td>${esc(r.producer_name)}</td><td>${esc(r.operation)}</td><td>${esc(r.attendant||'-')}</td><td>${num(r.equivalent_weight)} kg</td><td>${money(r.net_value)}</td><td><div class="row-actions"><button class="table-btn" onclick="showTicket(${r.id})">Ver</button><button class="table-btn edit" onclick="editTransaction(${r.id})">Editar</button></div></td></tr>`).join('')||'<tr><td colspan="9">Nenhum ticket encontrado.</td></tr>'}
