function ticketCopy(r,via){const cacao=r.product==='CACAU',nuts=r.product==='CASTANHAS',purchase=r.operation.startsWith('Compra'),title=purchase?'COMPROVANTE DE COMPRA':r.operation==='Depósito'?'COMPROVANTE DE DEPÓSITO':'COMPROVANTE DE MOVIMENTAÇÃO';const boxes=[['Peso bruto',num(r.gross_weight)+' kg'],['Peso líquido',num(r.physical_net_weight)+' kg'],[cacao||nuts?'Volumes':'Sacas',num(r.units)],['Umidade',num(r.moisture)+'%']];if(cacao){boxes.push(['Desc. fixo',num(r.fixed_discount)+' kg'],['Desc. umidade',num(r.moisture_discount)+' kg'],['Mofado informado',num(r.mold||0)+' kg'],['Desc. mofado (5%)',num(r.mold_discount||0)+' kg'],['Brocado informado',num(r.brocade||0)+' kg'],['Desc. brocado (20%)',num(r.brocade_discount||0)+' kg'])}else if(!nuts){boxes.push(['Tipo',r.subtype||'-'],['Defeitos',num(r.defects)])}else{boxes.push(['Desc. fixo',num(r.fixed_discount)+' kg'],['Desc. umidade',num(r.moisture_discount)+' kg'])}return `<section class="ticket-copy"><div class="ticket-header"><img src="./assets/logo-ouro-verde.png"><div><small>OURO VERDE ERP</small><h2>${title} — ${esc(r.product)}</h2><span>${via}</span></div><div class="ticket-number"><small>TICKET</small><b>${esc(r.ticket)}</b></div></div><div class="ticket-meta">${[['Data',dateBR(r.date)],['Ciclo/Lote',r.cycle],['Operação',r.operation],['Atendente',r.attendant||'NÃO INFORMADO']].map(x=>`<div class="ticket-box"><small>${x[0]}</small><b>${esc(x[1])}</b></div>`).join('')}</div><div class="ticket-producer">${[['Produtor',r.producer_name],['CPF/CNPJ',r.producer_cpf],['Código',r.producer_code],['Município',r.producer_city||'-']].map(x=>`<div class="ticket-box"><small>${x[0]}</small><b>${esc(x[1])}</b></div>`).join('')}</div><div class="ticket-values">${boxes.map(x=>`<div class="ticket-box"><small>${x[0]}</small><b>${esc(x[1])}</b></div>`).join('')}</div>${purchase?`<div class="ticket-finance">${[['Preço',cacao||nuts?money(r.price)+'/kg':money(r.price)+'/saca'],['Valor bruto',money(r.gross_value)],['Fundo Rural ('+num(r.rural_rate*100)+'%)','- '+money(r.rural_fund)],['VALOR LÍQUIDO',money(r.net_value)]].map((x,i)=>`<div class="ticket-box ${i===3?'ticket-total':''}"><small>${x[0]}</small><b>${x[1]}</b></div>`).join('')}</div>`:''}<div class="ticket-note"><b>Observações:</b> ${esc(r.notes||'Sem observações.')}${r.operation==='Depósito'?`<br>Depósito com vencimento em ${dateBR(r.expires_at)}. O produto permanece pertencendo ao produtor até compra ou retirada.`:''}</div><div class="ticket-attendant"><small>ATENDENTE RESPONSÁVEL</small><b>${esc(r.attendant||'NÃO INFORMADO')}</b></div><div class="signatures"><div>${esc(r.attendant||'Responsável Ouro Verde')}<br><small>Ouro Verde</small></div><div>Produtor</div></div><div class="ticket-footer">Cerealista Ouro Verde Importação e Exportação Ltda. • Jaru/RO</div></section>`}
window.showTicket=async id=>{try{const r=(await api('/api/transactions/'+id)).row;$('#ticketContent').innerHTML=`<main class="ticket-sheet">${ticketCopy(r,'VIA DO PRODUTOR')}${ticketCopy(r,'VIA DA CEREALISTA')}</main>`;$('#ticketModal').classList.remove('hidden')}catch(err){toast(err.message)}};
