let auditCache=[];
function auditBadge(status){const map={CONCILIADO:['OK','ok'],DIVERGENTE:['REVISAR','warn'],AUSENTE_NO_ERP:['AUSENTE','bad']};const v=map[status]||[status||'—',''];return `<span class="audit-badge ${v[1]}">${v[0]}</span>`}
async function loadAudit(){const box=$('#auditSummary');if(!box)return;const cycle=$('#auditCycle')?.value||'',status=$('#auditStatus')?.value||'',q=$('#auditSearch')?.value||'';const qs=new URLSearchParams({cycle,status,q});try{const d=await api('/api/audit?'+qs);auditCache=d.items||[];const sel=$('#auditCycle'),old=sel.value;sel.innerHTML='<option value="">Todos os lotes</option>'+d.batches.map(b=>`<option value="${esc(b.cycle)}">${esc(b.cycle)}</option>`).join('');sel.value=old;const imp=d.implementation||{},cards=[['Lotes auditados',d.batches.length],['Registros analisados',d.batches.reduce((n,b)=>n+(b.source_rows||0),0)],['Incluídos no ERP',(imp.safe_imported||[]).length],['Pendências bloqueadas',(imp.skipped_incomplete||[]).length]];box.innerHTML=cards.map(x=>`<article><small>${x[0]}</small><strong>${x[1]}</strong></article>`).join('')+`<div class="audit-batches">${d.batches.map(b=>`<button onclick="document.querySelector('#auditCycle').value='${esc(b.cycle)}';loadAudit()"><b>${esc(b.cycle)}</b><span>${b.source_rows} linhas • ${b.matched_rows} vinculadas • ${b.missing_in_erp} ausentes</span><em>${b.safe_imported||0} implantados</em></button>`).join('')}</div>`;$('#auditInfo').textContent=`${d.total} registro(s) encontrado(s). Registros incompletos permanecem bloqueados e não alteram o financeiro.`;$('#auditRows').innerHTML=auditCache.slice(0,1000).map(r=>`<tr><td><b>${esc(r.cycle)}</b></td><td>${r.source_row}</td><td>${esc(r.ticket||'—')}</td><td>${esc(r.producer_name||'—')}<small class="cell-sub">${esc(r.cpf_cnpj||'')}</small></td><td>${r.tx_date?dateBR(r.tx_date):'—'}</td><td>${num(r.net_weight)} kg</td><td>${auditBadge(r.erp_match_status)}</td><td>${esc(r.import_decision||'—')}</td><td><div class="audit-actions"><button onclick="openAuditAction(${r.id})">${r.erp_transaction_id?'✏ Editar':'＋ Implantar'}</button><button class="secondary" onclick="openAuditAction(${r.id},true)">⇄ Comparar</button></div></td></tr>`).join('')||'<tr><td colspan="9">Nenhum registro.</td></tr>'}catch(e){box.innerHTML=`<p>${esc(e.message)}</p>`}}

async function openAuditAction(id,compareOnly=false){try{const d=await api('/api/audit/'+id),r=d.audit,e=d.erp||{},f=$('#auditActionForm');f.reset();f.audit_id.value=id;const p=d.producer;$('#auditProducer').innerHTML='<option value="">Selecione...</option>'+allProducers.map(x=>`<option value="${x.id}">${esc(x.name)} — ${esc(x.cpf||'')}</option>`).join('');f.cycle.value=e.cycle||r.cycle||'';f.ticket.value=e.ticket||r.ticket||'';f.date.value=e.date||r.tx_date||'';f.operation.value=e.operation||(/dep[oó]sito/i.test(r.operation_expected||r.operation_source)?'Depósito':'Compra do Produtor');f.producer_id.value=e.producer_id||(p&&p.id)||'';f.gross_weight.value=e.gross_weight??r.gross_weight??'';f.net_weight.value=e.equivalent_weight??r.net_weight??'';f.moisture.value=e.moisture??r.moisture??'';f.price.value=e.price??r.price??'';f.gross_value.value=e.gross_value??r.gross_value??'';f.rural_fund.value=e.rural_fund??r.rural_fund??'';f.net_value.value=e.net_value??r.net_value??'';f.notes.value=e.notes??r.observation??'';$('#auditModalTitle').textContent=e.id?'Alterar lançamento existente':'Implantar lançamento ausente';$('#auditSaveButton').textContent=e.id?'Salvar alterações no ERP':'Implantar no ERP';const fields=[['Data',r.tx_date,e.date],['Ticket',r.ticket,e.ticket],['Tipo',r.operation_expected||r.operation_source,e.operation],['Peso bruto',num(r.gross_weight)+' kg',e.id?num(e.gross_weight)+' kg':'—'],['Peso líquido',num(r.net_weight)+' kg',e.id?num(e.equivalent_weight)+' kg':'—'],['Preço',r.price==null?'—':money(r.price),e.id?money(e.price):'—']];$('#auditCompare').innerHTML='<div class="audit-compare-head"><b>PLANILHA</b><b>ERP</b></div>'+fields.map(x=>`<div class="audit-compare-row"><span>${esc(x[0])}<b>${esc(x[1]||'—')}</b></span><span class="${String(x[1]||'')!==String(x[2]||'')?'different':''}">${esc(x[0])}<b>${esc(x[2]||'—')}</b></span></div>`).join('');$('#auditCompare').classList.toggle('expanded',compareOnly);$('#auditModal').classList.remove('hidden')}catch(err){toast(err.message)}}
$$('[data-audit-close]').forEach(x=>x.onclick=()=>$('#auditModal').classList.add('hidden'));
$('#auditActionForm').addEventListener('submit',async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));['producer_id','gross_weight','net_weight','moisture','price','gross_value','rural_fund','net_value'].forEach(k=>b[k]=b[k]===''?null:Number(b[k]));try{const d=await api('/api/audit/'+b.audit_id+'/apply',{method:'POST',body:JSON.stringify(b)});$('#auditModal').classList.add('hidden');await Promise.all([loadAudit(),loadTransactions(),loadDashboard(),renderReports()]);toast(d.mode==='created'?'Lançamento implantado no ERP':'Lançamento atualizado no ERP')}catch(err){toast(err.message)}});

