async function loadDeposits(){const product=$('#depositFilterProduct')?.value||'',cycle=$('#depositFilterCycle')?.value||'',cpf=onlyDigits($('#depositFilterCpf')?.value);const q=new URLSearchParams({product,cycle,cpf});const d=await api('/api/deposits-summary?'+q.toString());const sel=$('#depositFilterCycle');if(sel){const current=sel.value;sel.innerHTML='<option value="">Todos</option>'+d.cycles.map(x=>`<option>${esc(x)}</option>`).join('');sel.value=d.cycles.includes(current)?current:''}$('#depositKpis').innerHTML=[['Entradas em depósito',d.totals.deposited],['Baixas/Compras',d.totals.withdrawn],['Saldo disponível',d.totals.balance]].map(x=>`<article><small>${x[0]}</small><strong>${num(x[1])} kg</strong></article>`).join('');$('#depositRows').innerHTML=d.rows.map(r=>`<tr><td>${esc(r.product)}</td><td><b>${esc(r.cycle)}</b></td><td>${esc(r.producer_name)}</td><td>${esc(r.producer_cpf)}</td><td>${num(r.deposited)} kg</td><td>${num(r.withdrawn)} kg</td><td><b class="${r.balance<0?'negative':''}">${num(r.balance)} kg</b></td><td>${r.movements}</td></tr>`).join('')||'<tr><td colspan="8">Nenhum saldo localizado.</td></tr>'}
function fillDepositProducerOptions(){const sel=$('#depositProducerSelect');if(!sel)return;sel.innerHTML='<option value="">Selecione...</option>'+allProducers.map(p=>`<option value="${p.id}">${esc(p.name)} — ${esc(p.cpf||'')}</option>`).join('')}
function resolveDepositCpf(){const q=onlyDigits($('#depositCpfSearch')?.value),sel=$('#depositProducerSelect'),box=$('#depositProducerName');if(!sel)return;const p=allProducers.find(x=>onlyDigits(x.cpf)===q);if(p)sel.value=p.id;const chosen=allProducers.find(x=>String(x.id)===String(sel.value));if(box)box.innerHTML=chosen?`<b>${esc(chosen.name)}</b><span>${esc(chosen.cpf||'')} • Código ${esc(chosen.code||chosen.id)}</span>`:'Nenhum produtor selecionado.'}
document.addEventListener('input',e=>{if(e.target.id==='depositCpfSearch')resolveDepositCpf();if(e.target.id==='depositFilterCpf'){clearTimeout(window.depositFilterTimer);window.depositFilterTimer=setTimeout(loadDeposits,250)}});document.addEventListener('change',e=>{if(e.target.id==='depositProducerSelect')resolveDepositCpf();if(['depositFilterProduct','depositFilterCycle'].includes(e.target.id))loadDeposits()});
$('#depositAdjustmentForm')?.addEventListener('submit',async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));b.product=b.product;b.producer_id=Number(b.producer_id);b.gross_weight=Number(b.gross_weight);b.moisture=0;b.price=0;b.subtype='';b.defects=0;b.yield_value=0;b.mold=0;b.brocade=0;try{await api('/api/transactions',{method:'POST',body:JSON.stringify(b)});e.target.reset();e.target.date.value=new Date().toISOString().slice(0,10);fillDepositProducerOptions();resolveDepositCpf();await Promise.all([loadTransactions(),loadDeposits(),loadDashboard()]);toast('Movimento de depósito salvo')}catch(err){toast(err.message)}});

/* v26 - Central de Relatórios */
let reportView='daily';
function reportUniqueRows(rows){const seen=new Set();return rows.filter(r=>{const key=[r.id||'',r.cycle||'',r.ticket||'',r.date||'',r.producer_id||'',r.operation||'',Number(r.gross_weight||0).toFixed(4),Number(r.equivalent_weight||0).toFixed(4)].join('|');if(seen.has(key))return false;seen.add(key);return true})}
function reportTypeOf(r){if(['Depósito','Ajuste de Entrada'].includes(r.operation))return 'Depósito';if(['Compra do Café Depositado','Compra do Cacau Depositado','Retirada do Depósito','Ajuste de Saída'].includes(r.operation))return 'Baixa do Depósito';return 'Venda'}
function weightedPrice(rows){const sales=rows.filter(r=>(reportTypeOf(r)==='Venda'||String(r.operation).includes('Depositado'))&&+r.price>0&&+r.equivalent_weight>0);const kg=sales.reduce((a,r)=>a+(+r.equivalent_weight||0),0);return kg?sales.reduce((a,r)=>a+(+r.price||0)*(+r.equivalent_weight||0),0)/kg:0}
function reportInitFilters(){const rows=reportUniqueRows(allTransactions.filter(r=>r.product==='CACAU'));const cycles=[...new Set(rows.map(r=>r.cycle).filter(Boolean))].sort((a,b)=>a.localeCompare(b,undefined,{numeric:true}));const years=[...new Set(rows.map(r=>String(r.date||'').slice(0,4)).filter(Boolean))].sort();const cycle=$('#reportCycle'),year=$('#reportYear'),month=$('#reportMonth'),producer=$('#reportProducer');if(cycle&&cycle.options.length<=1)cycle.innerHTML='<option value="">Todos os lotes</option>'+cycles.map(x=>`<option>${esc(x)}</option>`).join('');if(year&&year.options.length<=1)year.innerHTML='<option value="">Todos</option>'+years.map(x=>`<option>${esc(x)}</option>`).join('');if(month&&month.options.length<=1)month.innerHTML='<option value="">Todos</option>'+Array.from({length:12},(_,i)=>`<option value="${String(i+1).padStart(2,'0')}">${new Date(2026,i,1).toLocaleDateString('pt-BR',{month:'long'})}</option>`).join('');if(producer&&producer.options.length<=1)producer.innerHTML='<option value="">Todos</option>'+allProducers.slice().sort((a,b)=>String(a.name).localeCompare(String(b.name))).map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}
function getReportRows(){let rows=reportUniqueRows(allTransactions.filter(r=>r.product==='CACAU'&&r.status!=='Cancelado'));const start=$('#reportStart')?.value,end=$('#reportEnd')?.value,month=$('#reportMonth')?.value,year=$('#reportYear')?.value,cycle=$('#reportCycle')?.value,type=$('#reportType')?.value,producer=$('#reportProducer')?.value;if(start)rows=rows.filter(r=>r.date>=start);if(end)rows=rows.filter(r=>r.date<=end);if(month)rows=rows.filter(r=>String(r.date).slice(5,7)===month);if(year)rows=rows.filter(r=>String(r.date).slice(0,4)===year);if(cycle)rows=rows.filter(r=>r.cycle===cycle);if(type)rows=rows.filter(r=>reportTypeOf(r)===type);if(producer)rows=rows.filter(r=>String(r.producer_id)===producer);return rows.sort((a,b)=>(a.date+String(a.id)).localeCompare(b.date+String(b.id)))}
function reportGroupDaily(rows){const m={};rows.forEach(r=>{const k=r.date||'Sem data';m[k]=m[k]||{gross:0,net:0};m[k].gross+=+r.gross_weight||0;m[k].net+=+r.equivalent_weight||0});return Object.entries(m).sort((a,b)=>a[0].localeCompare(b[0]))}
function renderReportChart(rows){const groups=reportGroupDaily(rows).slice(-31),max=Math.max(1,...groups.flatMap(([,v])=>[v.gross,v.net]));$('#reportWeightChart').innerHTML=groups.length?groups.map(([d,v])=>`<div class="weight-day" title="${dateBR(d)} — Bruto: ${num(v.gross)} kg | Líquido: ${num(v.net)} kg"><div class="weight-bars"><i class="gross" style="height:${Math.max(4,v.gross/max*150)}px"></i><i class="net" style="height:${Math.max(4,v.net/max*150)}px"></i></div><small>${String(d).slice(8,10)}/${String(d).slice(5,7)}</small></div>`).join(''):'<p>Sem dados para o filtro selecionado.</p>'}
function renderReports(){reportInitFilters();const rows=getReportRows(),sales=rows.filter(r=>reportTypeOf(r)==='Venda'||String(r.operation).includes('Depositado')),directSales=rows.filter(r=>r.operation==='Compra do Produtor'),storedSales=rows.filter(r=>String(r.operation).includes('Depositado')),depositEntries=rows.filter(r=>['Depósito','Ajuste de Entrada'].includes(r.operation)),depositOutputs=rows.filter(r=>['Compra do Café Depositado','Compra do Cacau Depositado','Retirada do Depósito','Ajuste de Saída'].includes(r.operation)),intakes=rows.filter(r=>['Compra do Produtor','Depósito','Ajuste de Entrada'].includes(r.operation)),sumRows=(arr,k)=>arr.reduce((a,r)=>a+(+r[k]||0),0),gross=sumRows(intakes,'gross_weight'),net=sumRows(intakes,'equivalent_weight'),depIn=sumRows(depositEntries,'equivalent_weight'),depOut=sumRows(depositOutputs,'equivalent_weight'),dep=depIn-depOut,sale=sumRows(directSales,'equivalent_weight')+sumRows(storedSales,'equivalent_weight'),diff=gross-net,grossValue=sumRows(sales,'gross_value'),fund=sumRows(sales,'rural_fund'),netValue=sumRows(sales,'net_value'),producers=new Set(rows.map(r=>r.producer_id)).size,avg=weightedPrice(rows);const cards=[['⚖','Peso bruto de entrada',num(gross)+' kg'],['◈','Peso líquido total',num(net)+' kg'],['▣','Saldo líquido em depósito',num(dep)+' kg'],['♟','Venda líquida do produtor',num(sale)+' kg'],['↓','Diferença bruto − líquido',num(diff)+' kg'],['🎫','Quantidade de tickets',rows.length]];$('#reportKpis').innerHTML=cards.map(c=>`<article><i>${c[0]}</i><small>${c[1]}</small><strong>${c[2]}</strong></article>`).join('');renderReportChart(rows);const depPct=net?Math.max(0,dep)/net*100:0,salePct=net?sale/net*100:0;$('#reportDonut').innerHTML=`<div class="donut" style="--dep:${depPct}%"><b>${num(net)}<small>kg</small></b></div><div class="donut-legend"><span><i class="dep"></i>Saldo depósito <b>${num(dep)} kg</b><em>${num(depPct)}%</em></span><span><i class="sale"></i>Venda <b>${num(sale)} kg</b><em>${num(salePct)}%</em></span></div>`;const now=new Date(),today=now.toISOString().slice(0,10),curMonth=today.slice(0,7);const all=reportUniqueRows(allTransactions.filter(r=>r.product==='CACAU'&&r.status!=='Cancelado'));$('#reportPrices').innerHTML=[['Média do dia',weightedPrice(all.filter(r=>r.date===today))],['Média do mês',weightedPrice(all.filter(r=>String(r.date).startsWith(curMonth)))],['Média do filtro/lote',avg]].map(x=>`<div><small>${x[0]}</small><strong>${money(x[1])}</strong></div>`).join('');const byProducer={};rows.forEach(r=>{const k=r.producer_id||r.producer_name;byProducer[k]=byProducer[k]||{name:r.producer_name||'Não informado',tickets:0,gross:0,net:0,value:0};const p=byProducer[k];p.tickets++;p.gross+=+r.gross_weight||0;p.net+=+r.equivalent_weight||0;p.value+=+r.net_value||0});const top=Object.values(byProducer).sort((a,b)=>b.net-a.net).slice(0,5);$('#reportTopRows').innerHTML=top.map((p,i)=>`<tr><td><b>${i+1}º</b></td><td>${esc(p.name)}</td><td>${p.tickets}</td><td>${num(p.gross)} kg</td><td><b>${num(p.net)} kg</b></td><td>${money(p.value)}</td></tr>`).join('')||'<tr><td colspan="6">Sem dados.</td></tr>';const cycle=$('#reportCycle').value;$('#reportSummaryTitle').textContent=cycle?`Resumo do lote ${cycle}`:'Resumo do período';const summary=[['Peso bruto de entrada',num(gross)+' kg'],['Peso líquido total',num(net)+' kg'],['Entradas em depósito',num(depIn)+' kg'],['Baixas do depósito',num(depOut)+' kg'],['Saldo líquido em depósito',num(dep)+' kg'],['Venda líquida do produtor',num(sale)+' kg'],['Diferença',num(diff)+' kg'],['Percentual de perda',num(gross?diff/gross*100:0)+'%'],['Quantidade de tickets',rows.length],['Quantidade de produtores',producers],['Preço médio ponderado',money(avg)],['Valor bruto total',money(grossValue)],['FUNRURAL total',money(fund)],['Valor líquido total',money(netValue)]];$('#reportSummary').innerHTML=summary.map((x,i)=>`<div class="${i===summary.length-1?'total':''}"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('');$('#reportCount').textContent=`${rows.length} registros`;$('#reportRows').innerHTML=rows.slice(-500).reverse().map(r=>`<tr><td><b>${esc(r.ticket)}</b></td><td>${dateBR(r.date)}</td><td>${esc(r.producer_name)}</td><td><span class="op">${reportTypeOf(r)}</span></td><td>${num(r.gross_weight)} kg</td><td><b>${num(r.equivalent_weight)} kg</b></td><td>${money(r.price)}</td><td>${money(r.net_value)}</td></tr>`).join('')||'<tr><td colspan="8">Nenhum lançamento encontrado.</td></tr>'}
function exportReportCsv(){const rows=getReportRows(),head=['Ticket','Data','Lote','Produtor','CPF/CNPJ','Tipo','Peso Bruto','Peso Líquido','Preço','Valor Bruto','FUNRURAL','Valor Líquido'],lines=[head,...rows.map(r=>[r.ticket,r.date,r.cycle,r.producer_name,r.producer_cpf,reportTypeOf(r),r.gross_weight,r.equivalent_weight,r.price,r.gross_value,r.rural_fund,r.net_value])].map(a=>a.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(';'));const blob=new Blob(['\ufeff'+lines.join('\n')],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='relatorio_cacau_'+new Date().toISOString().slice(0,10)+'.csv';a.click();URL.revokeObjectURL(a.href)}
document.addEventListener('click',e=>{if(e.target.matches('[data-report-view]')){$$('[data-report-view]').forEach(b=>b.classList.remove('active'));e.target.classList.add('active');reportView=e.target.dataset.reportView;renderReports()}if(e.target.id==='reportFilter'||e.target.id==='reportRefresh')renderReports();if(e.target.id==='reportExport')exportReportCsv();if(e.target.id==='reportPrint')printSection('Relatórios analíticos','#page-reports','landscape')});['reportStart','reportEnd','reportMonth','reportYear','reportCycle','reportType','reportProducer'].forEach(id=>document.addEventListener('change',e=>{if(e.target.id===id)renderReports()}));


async function loadCentral(){try{const [d,l]=await Promise.all([api('/api/operations-center'),api('/api/lots')]);const h=new Date().getHours(),saud=h<12?'Bom dia':h<18?'Boa tarde':'Boa noite';$('#centralGreeting').textContent=`${saud}, ${$('#userName').textContent||'Guilherme'}`;const map=Object.fromEntries(d.segments.map(x=>[x.product,x]));const cards=[['☕','Café hoje',num(map['CAFÉ']?.weight)+' kg'],['◉','Cacau hoje',num(map['CACAU']?.weight)+' kg'],['◈','Castanhas hoje',num(map['CASTANHAS']?.weight)+' kg'],['R$','Financeiro hoje',money(d.financial)],['▤','Saldo em depósitos',num(d.deposit_balance)+' kg'],['🎫','Tickets hoje',d.tickets],['♟','Produtores hoje',d.producers],['⚠','Pendências',d.pending.total]];$('#centralKpis').innerHTML=cards.map(x=>`<article class="central-kpi"><i>${x[0]}</i><small>${x[1]}</small><strong>${x[2]}</strong></article>`).join('');const pend=[['Auditoria pendente',d.pending.audit,'audit'],['Depósitos vencidos',d.pending.expired_deposits,'deposits'],['Saldos negativos',d.pending.negative_balances,'deposits']];$('#centralPending').innerHTML=pend.map(x=>`<button data-page="${x[2]}"><span>⚠ ${x[0]}</span><b>${x[1]}</b></button>`).join('');$('#centralPending').querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>showPage(b.dataset.page));$('#centralRecent').innerHTML=d.recent.map(r=>`<div class="recent-row"><div><b>${esc(r.producer_name||'Sem produtor')}</b><small>${dateBR(r.date)} • ${esc(r.product)} • ${esc(r.operation)} • ${esc(r.ticket)}</small></div><span>${num(r.equivalent_weight)} kg</span></div>`).join('')||'<p>Sem movimentos hoje.</p>';$('#centralLots').innerHTML=l.rows.slice(0,8).map(r=>`<button class="lot-card" data-product="${esc(r.product)}" data-cycle="${esc(r.cycle)}"><div><small>${esc(r.product)}</small><h4>LOTE ${esc(r.cycle)}</h4></div><b>${num(r.net)} kg</b><span>Preço médio ${money(r.average_price)}/kg • Eficiência ${num(r.efficiency)}%</span></button>`).join('')||'<p>Nenhum lote ativo.</p>';$('#centralLots').querySelectorAll('.lot-card').forEach(b=>b.onclick=()=>{currentDashboard=b.dataset.product;currentDashboardCycle=b.dataset.cycle;showPage('dashboard');loadDashboard()})}catch(err){toast(err.message)}}
$('#centralRefresh')?.addEventListener('click',loadCentral);

let globalTimer;$('#globalSearch')?.addEventListener('input',e=>{clearTimeout(globalTimer);const q=e.target.value.trim(),box=$('#globalResults');if(q.length<2){box.classList.add('hidden');return}globalTimer=setTimeout(async()=>{try{const d=await api('/api/global-search?q='+encodeURIComponent(q));box.innerHTML=d.rows.map(r=>`<button data-type="${r.type}" data-id="${r.id}"><b>${esc(r.title)}</b><small>${esc(r.subtitle)}</small></button>`).join('')||'<p>Nenhum resultado.</p>';box.classList.remove('hidden');box.querySelectorAll('button').forEach(b=>b.onclick=()=>{box.classList.add('hidden');if(b.dataset.type==='TICKET')showTicket(+b.dataset.id);else showProducerProfile(+b.dataset.id)})}catch(err){toast(err.message)}},250)});
document.addEventListener('click',e=>{if(!e.target.closest('.global-search'))$('#globalResults')?.classList.add('hidden')});
async function showProducerProfile(id){try{const d=await api(`/api/producer/${id}/summary`),s=d.summary,p=d.producer;$('#profileName').textContent=p.name;$('#profileContent').innerHTML=`<div class="profile-head"><div><small>CÓDIGO</small><b>${esc(p.code||p.id)}</b></div><div><small>CPF/CNPJ</small><b>${esc(p.cpf||'-')}</b></div><div><small>CIDADE</small><b>${esc(p.city||'-')}</b></div><div><small>TELEFONE</small><b>${esc(p.phone||'-')}</b></div></div><div class="profile-kpis"><div><small>Peso bruto</small><b>${num(s.gross)} kg</b></div><div><small>Peso líquido</small><b>${num(s.net)} kg</b></div><div><small>Preço médio</small><b>${money(s.average_price)}/kg</b></div><div><small>Saldo depósito</small><b>${num(s.deposit_balance)} kg</b></div><div><small>Valor recebido</small><b>${money(s.value)}</b></div><div><small>Último lote</small><b>${esc(s.last_cycle||'-')}</b></div></div><h4>Linha do tempo</h4><div class="timeline">${d.timeline.map(t=>`<div><time>${dateBR(t.date)}</time><span class="timeline-dot"></span><section><b>${esc(t.operation)} • ${esc(t.product)}</b><small>Ticket ${esc(t.ticket)} • Lote ${esc(t.cycle)} • ${num(t.equivalent_weight)} kg</small></section></div>`).join('')||'<p>Sem movimentos.</p>'}</div>`;$('#producerProfileModal').classList.remove('hidden')}catch(err){toast(err.message)}}
$$('[data-close-profile]').forEach(x=>x.onclick=()=>$('#producerProfileModal').classList.add('hidden'));
